/* PAUL MURRELL
   This is verbatim from the GNU plotutils libplot-2.3 distribution
*/

/* This file defines the arrays OCCIDENTAL_HERSHEY_GLYPHS and
ORIENTAL_HERSHEY_GLYPHS.  The first array includes the standard
(`occidental') Hershey glyphs digitized by Dr. Allen V. Hershey, some
glyphs due to other people, and his Japanese Hiragana and Katakana
glyphs.  The second array includes his digitizations of Japanese
ideographic symbols (Kanji glyphs).  It originally included the Hiragana
and Katakana glyphs as well, but they were moved to the first array
because some people may not wish to include Kanji support.

Dr. Hershey digitized the glyphs c. 1967, at what is now the U.S. Naval
Surface Weapons Center in Dahlgren, Virginia.

The format of the glyphs in the OCCIDENTAL_HERSHEY_GLYPHS and
ORIENTAL_HERSHEY_GLYPHS arrays is the format in which the Hershey
glyphs were distributed to mod.sources in 1985(?) by Pete Holzmann, and
is due to Jim Hurt, then at Cognition Inc.  Glyphs are encoded as
strings consisting of pairs of printable ascii characters in the range
0x20 to 0x7e, i.e. SP (ascii space) through ~ (ascii tilde).  Each
character in the range [0x20,0x7e] encodes an integer.  The integer may
be obtained from the character by subtracting 'R', i.e, 0x52.  Integers
in the range [-0x32,0x2c], i.e., [-50,44], may be represented in this
way.  Actually, all integers appearing in the occidental Hershey glyphs
are restricted to the range [-41,41], and those in the oriental glyphs
are restricted to the range [-12,13].

The first two characters in each string encode the x range
(xinit,xfinal) of a glyph.  (The `width' of the glyph, as distinct from
the x extent of its bounding box, is xfinal - xinit.)  Subsequent pairs
encode (x1,y1),(x2,y2),(x3,y3),..., i.e., the coordinates of points.
The glyph is drawn by moving to (x1,y1), stroking a vector to (x2,y2),
stroking a vector to (x3,y3), etc.  The pair (-50,0), which is encoded
as the pair of characters " R", if encountered in the string is
interpreted as a `pen up' command: the vector immediately following
should be drawn with pen up, i.e., should be interpreted as a motion
command rather than a drawing command.

NOTE: The pointing hand glyphs in slots 4040..4043 contain non-ASCII
bytes (e.g., 0x84, 0x80).  The arrays are stored as &[u8] byte slices
to accommodate these values. */

/*
 * Port of R's src/main/g_her_glyph.c (629 lines)
 *
 * This file was originally from the GNU plotutils libplot-2.3 distribution.
 * It contains the Hershey vector font glyph data used by R's graphics engine
 * for rendering text using Hershey fonts.
 */

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/// Number of occidental Hershey glyphs (should agree with value in g_cntrlify.c)
pub const NUM_OCCIDENTAL_HERSHEY_GLYPHS: usize = 4400;

/// Number of oriental Hershey glyphs (should agree with value in g_cntrlify.c)
pub const NUM_ORIENTAL_HERSHEY_GLYPHS: usize = 5500;

/// Position of `undefined character' symbol (a bundle of horizontal lines)
/// in the Hershey OCCIDENTAL_HERSHEY_GLYPHS array.
/// NOTE: position of this glyph is #defined as `UNDE' in g_extern.h
pub const UNDE: usize = 4023;

use std::os::raw::c_int;

// ---------------------------------------------------------------------------
// Hershey font index constants (from g_extern.h)
// ---------------------------------------------------------------------------

/// Hershey font indices (should agree with the numbering in g_fontdb.c)
pub const HERSHEY_SERIF: c_int = 0;
pub const HERSHEY_SERIF_ITALIC: c_int = 1;
pub const HERSHEY_SERIF_BOLD: c_int = 2;
pub const HERSHEY_CYRILLIC: c_int = 4;
pub const HERSHEY_HIRAGANA: c_int = 6; // hidden font
pub const HERSHEY_KATAKANA: c_int = 7; // hidden font
pub const HERSHEY_EUC: c_int = 8;
pub const HERSHEY_GOTHIC_GERMAN: c_int = 16;
pub const HERSHEY_SERIF_SYMBOL: c_int = 18;

// ---------------------------------------------------------------------------
// Accent type constants (from g_extern.h)
// ---------------------------------------------------------------------------

/// Accent types for composite characters in Hershey fonts
pub const ACC0: c_int = 16384 + 0; // superimpose on character
pub const ACC1: c_int = 16384 + 1; // elevate by 7 Hershey units
pub const ACC2: c_int = 16384 + 2; // same, also shift right by 2 units

/// Flag in a Hershey glyph number indicating a `small Kana'
pub const KS: c_int = 8192; // i.e. 0x200

// ---------------------------------------------------------------------------
// Occidental Hershey Glyphs
// ---------------------------------------------------------------------------

